#!/bin/bash
# SELF-CONTAINED W-attack probe: dedicated root-translation branch + z-weighted
# transl loss (Cyrus engineering ask). Runs BOTH configs back-to-back so one job
# gives the loss-weight-only baseline (exp_p3_wabs) and the new levers
# (exp_p3_roottrans) side by side. Read: WRIST (abs root placement, the target),
# RR_MPJPE (articulation guardrail, must NOT regress), MPJPE (abs, W proxy).
# Stream via:  srun --account=3dv --partition=jobs --gpus=gb10:1 bash < roottrans_selfcontained.sh 2>&1 | tee ~/rt_log.txt
set -uo pipefail
SRC=/home/dmonopoli/FF-4DGS-Ego
EXPECT_SHA="c9aa1c0d75df73e818ad51b1036442a0d2cf360687dc92967773f7ddccb3e29c"
export XDG_CACHE_HOME=/tmp/xc TORCH_HOME=/tmp/th HF_HOME=/tmp/hf MPLCONFIGDIR=/tmp/mpl
mkdir -p /tmp/xc /tmp/th /tmp/hf /tmp/mpl
echo "=== ROOTTRANS PROBE @ $(date) on $(hostname) arch=$(uname -m) ==="

# --- 1. decode embedded bundle of changed files ---
cat > /tmp/_rt_bundle.b64 <<'RTB64EOF'

RTB64EOF
base64 -d /tmp/_rt_bundle.b64 > /tmp/_rt_bundle.tgz
GOT_SHA=$(sha256sum /tmp/_rt_bundle.tgz | awk '{print $1}')
echo "bundle sha256: $GOT_SHA"
if [ "$GOT_SHA" != "$EXPECT_SHA" ]; then echo "!! SHA MISMATCH (expected $EXPECT_SHA) -- aborting"; exit 3; fi
cd "$SRC" && tar xzf /tmp/_rt_bundle.tgz && echo "=== unpacked 5 files into $SRC ==="

source /work/scratch/dmonopoli/venv_gb10/bin/activate
python -c "import torch;print('torch',torch.__version__,'cuda',torch.cuda.is_available())"

run_one () {
  CFG="$1"
  RUN="/tmp/run_$(basename "$CFG" .yaml)"
  rm -rf "$RUN"; mkdir -p "$RUN"
  cp -r "$SRC/scripts" "$RUN/scripts"
  ln -sfn "$SRC/diffsynth" "$RUN/diffsynth"
  ln -sfn "$SRC/models"    "$RUN/models"
  ln -sfn "$SRC/configs"   "$RUN/configs"
  cd "$RUN"
  echo ""
  echo "######## BEGIN $CFG @ $(date) ########"
  python -u -m scripts.train_hand_head --config "$CFG" \
     training.output_dir=/tmp/rtout training.val_every=2 training.log_every=1 \
     training.val_max_batches=12 debug.enabled=true debug.max_sequences=8 2>&1 \
     | grep --line-buffered -vE "Loaded GT joints|Loaded 2D GT|No calibration for|\[VIS\]"
  echo "######## END $CFG rc=${PIPESTATUS[0]} @ $(date) ########"
}

# wabs first (loss-weight-only baseline), then roottrans (both new levers)
run_one configs/exp_p3_wabs.yaml
run_one configs/exp_p3_roottrans.yaml
echo ""
echo "=== ALL DONE @ $(date) ==="
echo "Compare the LAST 'hand_metrics(all)' line of each ######## block:"
echo "  WRIST should drop most under roottrans; RR_MPJPE must stay ~flat."
